const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry and time
  const lon = 140.878144;
  const lat = 27.245974;
  const point = ee.Geometry.Point([lon, lat]);
  const bufferDist = 2000; // 2 km in meters
  const searchRadius = ee.Geometry.Point([lon, lat]).buffer(bufferDist);

  const startDate = '2014-03-25';
  const endDate = '2014-04-04';

  // 2. Acquire Landsat 8 imagery (started Feb 2013)
  let col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(searchRadius)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  let size = col.size().getInfo();
  console.log(`Landsat 8 Images (Mar 2014): ${size}`);

  // Fallback to Landsat 7 if no L8 data
  if (size === 0) {
    col = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(searchRadius)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));
    size = col.size().getInfo();
    console.log(`Fallback to Landsat 7 Images: ${size}`);
  }

  if (size === 0) {
    console.log('No data found for location/date.');
    console.log('C1');
    return;
  }

  // 3. Select first available image
  const img = col.first();

  // 4. Calculate NDVI to identify land
  const ndvi = img.normalizedDifference(['SR_B5', 'SR_B4']);

  // 5. Create land mask (NDVI > 0.3 typically indicates vegetation/land)
  const landMask = ndvi.gt(0.2);

  // 6. Count land pixels in the 2km buffer
  const landPixelCount = landMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: searchRadius,
    scale: 30,
    maxPixels: 1e9
  }).get('nd').getInfo();

  console.log(`Valid land pixels in 2km radius: ${landPixelCount}`);

  if (landPixelCount === null || landPixelCount === 0) {
    console.log('No valid land pixels detected.');
    console.log('C2');
    return;
  }

  // 7. Use connected components to identify isolated island clusters
  const landPixels = landMask.updateMask(landMask);
  const connected = landPixels.connectedComponents(ee.Kernel.plus(1), 256);

  // 8. Count unique clusters (islands)
  const clusterCount = connected.reduceRegion({
    reducer: ee.Reducer.countDistinct(),
    geometry: searchRadius,
    scale: 30,
    maxPixels: 1e9
  }).get('labels').getInfo();

  console.log(`Island clusters detected: ${clusterCount}`);

  if (clusterCount === null) {
    console.log('Cluster calculation failed.');
    console.log('C3');
    return;
  }

  // 9. Final answer
  if (clusterCount === 2) {
    console.log('Two isolated islands confirmed within 2km radius.');
    console.log('A');
  } else {
    console.log(`Found ${clusterCount} clusters, not exactly 2 islands.`);
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
